static long compressTimeBucket(long timeBucket, int dayStep) {
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket / 100) % 100);
    int day = (int) (timeBucket % 100);

    int adjustedDay = (day / dayStep) * dayStep;
    if (day % dayStep != 0) {
        adjustedDay += dayStep;
    }
    adjustedDay = Math.min(adjustedDay, getDaysInMonth(year, month));

    return year * 10000 + month * 100 + adjustedDay;
}

static int getDaysInMonth(int year, int month) {
    int[] daysInMonth = { 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 };
    if (month == 2 && isLeapYear(year)) {
        return 29;
    }
    return daysInMonth[month - 1];
}

static boolean isLeapYear(int year) {
    return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            size++;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(c)) {
            size += 4; // surrogate pair
            i++; // skip the low surrogate
        } else {
            size += 3;
        }
    }
    return size;
}

