public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    String path = u.getRawPath();
    if (path != null && !path.isEmpty()) {
        // If the path is absolute, skip the leading '/'
        int start = path.startsWith("/") ? 1 : 0;
        String[] segments = path.substring(start).split("/");
        for (String segment : segments) {
            if (decode) {
                try {
                    segment = URLDecoder.decode(segment, StandardCharsets.UTF_8.toString());
                } catch (UnsupportedEncodingException e) {
                    // Handle the exception according to your application's needs
                    throw new RuntimeException(e);
                }
            }
            pathSegments.add(new PathSegmentImpl(segment, null));
        }
    }
    return pathSegments;
}

