private String parseToken(final char[] terminators){
    StringBuilder token = new StringBuilder();
    int currentIndex = this.currentIndex; // Assuming currentIndex is the current position in the input string
    while (currentIndex < input.length()) { // Assuming input is the string being parsed
        char currentChar = input.charAt(currentIndex);
        boolean isTerminator = false;
        for (char terminator : terminators) {
            if (currentChar == terminator) {
                isTerminator = true;
                break;
            }
        }
        if (isTerminator) {
            break;
        }
        token.append(currentChar);
        currentIndex++;
    }
    this.currentIndex = currentIndex; // Update the currentIndex for the next call
    return token.toString();
}

