public static String applyRelativePath(String path, String relativePath) {
    // Normalize the path by removing any double slashes and trailing slashes
    path = path.replaceAll("/+", "/");
    if (path.endsWith("/")) {
        path = path.substring(0, path.length() - 1);
    }

    // Split the relative path into segments
    String[] segments = relativePath.split("/");

    // Use a stack to process the path segments
    java.util.Stack<String> stack = new java.util.Stack<>();
    for (String segment : path.split("/")) {
        stack.push(segment);
    }

    // Process each segment of the relative path
    for (String segment : segments) {
        if (segment.equals("..")) {
            if (!stack.isEmpty()) {
                stack.pop(); // Move up one directory
            }
        } else if (segment.equals(".")) {
            // Do nothing, current directory
        } else if (!segment.isEmpty()) {
            stack.push(segment); // Move down into a directory
        }
    }

    // Build the final path
    StringBuilder finalPath = new StringBuilder();
    for (String segment : stack) {
        if (finalPath.length() > 0) {
            finalPath.append("/");
        }
        finalPath.append(segment);
    }

    return finalPath.toString();
}

